        organizationId?.let { query.add(QueryParam("organization_id", it)) }
        return transport.request<Page<UserApiKey>>(
            method = "GET",
            path = path,
            query = query,
            body = null,
            options = requestOptions,
        )
    }

    /**
     * Auto-paginating variant of [listApiKeys]: emits every item across successive pages as the flow is collected.
     *
     * @param userId Unique identifier of the user.
     * @param before An object ID that defines your place in the list. When the ID is not present, you are at the end of the list.
     * @param limit Upper limit on the number of objects to return, between `1` and `100`.
     * @param order Order the results by the creation time.
     * @param organizationId The ID of the organization to filter user API keys by. When provided, only API keys created against that organization membership are returned.
     * @param requestOptions Per-request overrides: extra headers, timeout, retries, base URL, idempotency key.
     * @return A cold flow of `UserApiKey` values.
     */
    public fun listApiKeysAutoPaging(
        userId: String,
        before: String? = null,
        limit: Long? = null,
        order: PaginationOrder? = null,
        organizationId: String? = null,
        requestOptions: RequestOptions? = null,
    ): Flow<UserApiKey> =
        autoPagingFlow { cursor ->
            listApiKeys(
                userId = userId,
                before = if (cursor == null) before else null,
                after = cursor,
                limit = limit,
                order = order,
                organizationId = organizationId,
                requestOptions = requestOptions,
            )
        }

    /**
     * Create an API key for a user
     *
     * Create a new API key owned by a user. The user must have an active membership in the specified organization.
     *
     * @param userId Unique identifier of the user.
     * @param name A descriptive name for the API key.
     * @param organizationId The ID of the organization the user API key is associated with. The user must have an active membership in this organization.
     * @param permissions The permission slugs to assign to the API key. Each permission must be enabled for user API keys.
     * @param expiresAt The timestamp when the API key should expire. Must be a future timestamp. If omitted, the key does not expire.
     * @param requestOptions Per-request overrides: extra headers, timeout, retries, base URL, idempotency key.
     * @return The `UserApiKeyWithValue` returned by the API.
     */
    public suspend fun createApiKey(
        userId: String,
        name: String,
        organizationId: String,
        permissions: List<String>? = null,
        expiresAt: Instant? = null,
        requestOptions: RequestOptions? = null,
    ): UserApiKeyWithValue {
        val path = "user_management/users/${PathEncoding.segment(userId)}/api_keys"
        val payload = JsonBody()
        payload.set("name", name)
        payload.set("organization_id", organizationId)
        payload.set("permissions", permissions)
        payload.set("expires_at", expiresAt)
        return transport.request<UserApiKeyWithValue>(
            method = "POST",
            path = path,
            query = emptyList(),
            body = payload,
            options = requestOptions,
        )
    }
}
